// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    Rejecter rejecter;

    function setUp() public {
        c = new MyContract();
        rejecter = new Rejecter();
    }

    function testFuzz_property(uint96 amount) public {
        vm.assume(amount > 0);
        vm.deal(address(c), uint256(amount));
        bool ok;
        try c.sendTo(address(rejecter), uint256(amount)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertFalse(ok);
    }
}

contract Rejecter {
    receive() external payable {
        revert();
    }
}
